   {"Chưa đo được","Not measured"},{"Không đọc được dữ liệu khu vực này trong lần kiểm tra vừa rồi.","This area could not be read during the last check."},{"Chưa đo","Not measured"},
   {"Rất tốt","Excellent"},{"Tốt","Good"},{"Nên dọn","Worth cleaning"},{"Cần dọn","Needs cleaning"},{"Cần xử lý ngay","Act now"},{"Khẩn","Urgent"},{"Nên xem","Review"},
   {"Máy đang sạch. Không có gì cần dọn ở các khu vực đã kiểm tra.","This PC is clean. Nothing to clean in the checked areas."},
   {" Có thể giải phóng khoảng {0}."," About {0} can be freed."},{"{0} khu vực cần chú ý.","{0} areas need attention."},{" Nên dọn ngay để máy nhẹ hơn."," Clean now to lighten the PC."},
   {"Chưa kiểm tra","Not checked yet"},{"Đang kiểm tra…","Checking…"},
   {"Bấm Kiểm tra ngay để đo tệp rác, phần còn sót, thư mục rỗng, kho khôi phục, mục khởi động và dung lượng trống. Chỉ đọc, không thay đổi gì.","Click Check now to measure junk, leftovers, empty folders, the vault, startup entries and free space. Read-only; nothing changes."},
   {"Có thể giải phóng: {0}   •   {1} khu vực cần chú ý   •   Kiểm tra lúc {2}","Reclaimable: {0}   •   {1} areas need attention   •   Checked at {2}"},
   {"Tweek Pro – Kiểm tra sức khỏe máy {0}","Tweek Pro – PC health check {0}"},{"Điểm: {0}/100 ({1} – {2}). {3}","Score: {0}/100 ({1} – {2}). {3}"},{"chưa đo","not measured"},
   {"Đang đo tệp rác theo quy tắc…","Measuring rule-matched junk…"},{"Đang đo kho khôi phục…","Measuring the recovery vault…"},{"Đang đếm mục khởi động…","Counting startup entries…"},{"Đang tìm thư mục rỗng trong Downloads…","Finding empty folders in Downloads…"},{"Đang đọc dung lượng trống…","Reading free space…"},
   {"Kiểm tra sức khỏe: {0}/100 ({1}). {2}","Health check: {0}/100 ({1}). {2}"},{"Đã dừng kiểm tra sức khỏe.","Health check stopped."},{"Đã sao chép báo cáo sức khỏe vào clipboard.","Health report copied to the clipboard."},
   {"Chọn một dòng kết quả trước.","Select a result row first."},{"Không tìm thấy tab {0}.","Tab {0} not found."},{"Chưa có báo cáo. Bấm Kiểm tra ngay trước.","No report yet. Click Check now first."},

   // Windows apps (Appx/MSIX)
   {"Ứng dụng Windows","Windows Apps"},{"App Windows","Windows app"},{"Gói","Package"},{"Nguồn","Origin"},{"Gỡ cho mọi tài khoản","Remove for all accounts"},{"Không cài lại cho tài khoản mới","Do not reinstall for new accounts"},{"Hiện thành phần được bảo vệ","Show protected components"},
   {"Mở trong Microsoft Store","Open in Microsoft Store"},{"Mở thư mục gói","Open package folder"},{"Gỡ được","Removable"},{"Cần cân nhắc","Use caution"},{"Được bảo vệ","Protected"},{"Được bảo vệ (chỉ xem)","Protected (view only)"},{"Khác","Other"},
   {"Ứng dụng cài sẵn của Windows và ứng dụng Microsoft Store (gói Appx/MSIX). Gỡ qua Remove-AppxPackage của Windows; các thành phần cốt lõi (Start, Search, Settings, Windows Security, thư viện nền…) bị khóa trong mã và không thể chọn. Mục “Cần cân nhắc” gỡ được nhưng hữu ích (Store, App Installer, Photos…). Khôi phục: đăng ký lại từ thư mục gói nếu còn, hoặc cài lại từ Microsoft Store.","Windows inbox apps and Microsoft Store apps (Appx/MSIX packages). Removal uses Windows' own Remove-AppxPackage; core components (Start, Search, Settings, Windows Security, frameworks…) are locked in code and cannot be selected. “Use caution” items are removable but useful (Store, App Installer, Photos…). Restore: re-register from the package folder when it still exists, or reinstall from Microsoft Store."},
   {"Chưa tải danh sách.\r\nBấm Tải danh sách để đọc các gói Appx/MSIX đã cài (Get-AppxPackage). Chỉ đọc; chưa có gì bị thay đổi.","List not loaded.\r\nClick Load list to read the installed Appx/MSIX packages (Get-AppxPackage). Read-only; nothing changes."},
   {"Đang đọc danh sách gói qua PowerShell…","Reading the package list through PowerShell…"},{"Không đọc được gói nào.","No packages could be read."},{"Mọi gói đều được bảo vệ; bật “Hiện thành phần được bảo vệ” để xem.","Every package is protected; enable “Show protected components” to view them."},
   {"Ứng dụng Windows: {0} gói, {1} gỡ được, {2} được bảo vệ.","Windows apps: {0} packages, {1} removable, {2} protected."},{"{0} gói  •  {1} gỡ được  •  {2} được bảo vệ  •  Đã chọn {3}","{0} packages  •  {1} removable  •  {2} protected  •  Selected {3}"},{"  •  có mục cần cân nhắc","  •  includes caution items"},
   {"Đánh dấu ứng dụng muốn gỡ (thành phần được bảo vệ không thể chọn).","Check the apps to remove (protected components cannot be selected)."},{" cho mọi tài khoản"," for all accounts"},
   {"Gỡ {0} ứng dụng Windows{1}?\r\n\r\n{2}\r\n\r\nGỡ bằng Remove-AppxPackage. Khôi phục: đăng ký lại từ thư mục gói nếu Windows còn giữ, hoặc cài lại từ Microsoft Store.","Remove {0} Windows apps{1}?\r\n\r\n{2}\r\n\r\nRemoval uses Remove-AppxPackage. Restore: re-register from the package folder if Windows still keeps it, or reinstall from Microsoft Store."},
   {"\r\n\r\nBỏ provisioning: tài khoản Windows tạo mới cũng sẽ không có ứng dụng này.","\r\n\r\nDeprovision: newly created Windows accounts will not get this app either."},
   {"{0} mục thuộc nhóm “Cần cân nhắc”:\r\n{1}\r\n\r\nĐây là thành phần hữu ích của Windows (ví dụ Microsoft Store dùng để cài lại app khác). Vẫn gỡ?","{0} items are in the “Use caution” group:\r\n{1}\r\n\r\nThese are useful Windows components (for example Microsoft Store is needed to reinstall other apps). Remove anyway?"},
   {"Đang gỡ ứng dụng Windows: ","Removing Windows app: "},{"Đã gỡ: ","Removed: "},{"Không gỡ được ","Could not remove "},{"Ứng dụng chưa gỡ","App not removed"},{"Đã gỡ {0} ứng dụng Windows; lỗi {1}.","Removed {0} Windows apps; {1} errors."},{"Kết quả gỡ ứng dụng Windows","Windows app removal result"},
   {"Chọn một ứng dụng trước.","Select an app first."},{"Thư mục gói không tồn tại hoặc không đọc được.","The package folder does not exist or cannot be read."},
   {"Gỡ được; cài lại từ Microsoft Store khi cần.","Removable; reinstall from Microsoft Store when needed."},{"Gỡ được nhưng nên cân nhắc: thành phần hữu ích của Windows hoặc cần để cài app khác.","Removable, but think twice: a useful Windows component or needed to install other apps."},
   {"Thư viện nền (framework) mà app khác phụ thuộc; Windows tự dọn khi không còn ai dùng.","Framework package other apps depend on; Windows removes it when nothing uses it."},{"Windows đánh dấu không thể gỡ.","Marked non-removable by Windows."},{"Thành phần cốt lõi của Windows (Start, Search, Settings, đăng nhập…); gỡ sẽ làm hỏng hệ thống.","Core Windows component (Start, Search, Settings, sign-in…); removing it breaks the system."},
   {"Không đọc được danh sách ứng dụng Windows: ","Could not read the Windows app list: "},{"Thành phần được bảo vệ, không gỡ: ","Protected component, not removed: "},{"Tên gói không hợp lệ: ","Invalid package name: "},{"Thư mục gói không hợp lệ: ","Invalid package folder: "},
   {"Đã gỡ gói; khôi phục = đăng ký lại từ thư mục gói nếu còn, hoặc cài lại từ Microsoft Store.","Package removed; restore = re-register from the package folder if present, or reinstall from Microsoft Store."},{"Đăng ký lại gói thất bại: ","Re-registering the package failed: "},{"Thư mục gói không còn; đã mở trang Microsoft Store của {0} để cài lại.","The package folder is gone; opened the Microsoft Store page of {0} to reinstall."},{"Không phải bản sao lưu ứng dụng Windows.","Not a Windows app backup."},
   {"Không tìm thấy Windows PowerShell; tính năng này chỉ chạy trên Windows.","Windows PowerShell not found; this feature runs on Windows only."},{"PowerShell không phản hồi trong thời gian cho phép.","PowerShell did not respond within the allowed time."},

   // Vault states and stubborn files
   {"{0} bản sao lưu ({1} trên đĩa)  •  Đã đánh dấu {2} ({3})  •  Khôi phục dùng dòng đang chọn; xóa vĩnh viễn dùng ô đánh dấu.","{0} backups ({1} on disk)  •  Marked {2} ({3})  •  Restore uses the selected row; permanent delete uses the checkboxes."},
   {"Đã sao lưu","Backed up"},{"Đã khôi phục","Restored"},{"Cần kiểm tra","Needs review"},{"Hẹn xóa khi khởi động lại","Delete at next reboot"},
   {"bỏ thuộc tính chỉ đọc/ẩn/hệ thống của {0} mục","cleared read-only/hidden/system on {0} entries"},{"chiếm quyền sở hữu và cấp toàn quyền cho Administrators","took ownership and granted Administrators full control"},
   {"{0} mục vẫn bị Windows chặn dù đã bỏ thuộc tính và chiếm quyền sở hữu (thường do một tiến trình đang giữ tệp):\r\n\r\n{1}\r\n\r\nHẹn xóa các mục này khi khởi động lại Windows? Chúng sẽ bị xóa thẳng lúc khởi động, KHÔNG có bản sao lưu để khôi phục.","Windows still blocks {0} items after clearing attributes and taking ownership (usually a process is holding the files):\r\n\r\n{1}\r\n\r\nSchedule them for deletion at the next Windows restart? They will be deleted directly at boot, with NO backup to restore."},
   {"Đã hẹn xóa khi khởi động lại: ","Scheduled for deletion at reboot: "},{"Vẫn bị chặn sau khi chiếm quyền sở hữu; có thể đang bị một tiến trình giữ. Đóng ứng dụng liên quan rồi thử lại.","Still blocked after taking ownership; a process may be holding it. Close the related application and try again."},

   // Junk cleaner runtime texts
   {"Bị khóa","Locked"},{"Chưa xem trước","Not previewed"},{"Không có gì để dọn","Nothing to clean"},{"Có thể dọn (chưa đủ)","Cleanable (partial)"},{"Có thể dọn","Cleanable"},
   {"{0} quy tắc  •  Đã chọn {1} nhóm, {2} tệp, {3}","{0} rules  •  Selected {1} groups, {2} files, {3}"},
   {"  •  XÓA THẲNG: không thể khôi phục","  •  DIRECT DELETE: cannot be undone"},{"  •  Chuyển vào Kho: chưa giải phóng dung lượng cho đến khi xóa vĩnh viễn trong kho","  •  Move to Vault: space is freed only after permanent deletion in the vault"},
   {"Xóa thẳng mục đã chọn","Delete selected directly"},{"Dọn mục đã chọn (vào kho)","Clean selected (to vault)"},
   {"Xem trước xong: {0} tệp, {1}","Preview done: {0} files, {1}"},{"  •  {0} nhóm bị khóa (di chuột lên dòng đỏ để xem lý do)","  •  {0} groups locked (hover a red row for the reason)"},
   {"Không có tệp rác đủ điều kiện theo quy tắc hiện tại.\r\nTệp mới hơn {0} giờ và tệp đang mở không được tính.","No junk matches the current rules.\r\nFiles newer than {0} hours and open files are not counted."},
   {"Đã dừng xem trước.","Preview stopped."},{"Xem trước rồi đánh dấu nhóm muốn dọn.","Preview first, then check the groups to clean."},
   {"XÓA THẲNG {0} tệp ({1}) mà KHÔNG lưu bản khôi phục?\r\n\r\n{2}\r\n\r\nThao tác này không thể hoàn tác. Chỉ tiếp tục khi chắc chắn các nhóm trên chỉ chứa bộ đệm/tệp tạm.","DELETE {0} files ({1}) DIRECTLY without a recovery copy?\r\n\r\n{2}\r\n\r\nThis cannot be undone. Continue only if you are sure the groups above hold nothing but caches/temporary files."},
   {"Xác nhận xóa vĩnh viễn","Confirm permanent deletion"},{"Xác nhận lần cuối: xóa thẳng {0} tệp, không có bản sao lưu?","Final confirmation: delete {0} files directly, with no backup?"},
   {"Chuyển {0} tệp ({1}) vào Kho khôi phục?\r\n\r\n{2}\r\n\r\nMỗi nhóm tạo một bản sao lưu; có thể khôi phục hoặc xóa vĩnh viễn sau trong tab Kho khôi phục. Dung lượng ổ đĩa chưa được giải phóng cho đến khi xóa vĩnh viễn.","Move {0} files ({1}) to the Recovery Vault?\r\n\r\n{2}\r\n\r\nEach group creates one backup; you can restore or permanently delete it later in the Recovery Vault tab. Disk space is freed only after permanent deletion."},
   {"Đang xóa thẳng…","Deleting directly…"},{"Đang chuyển vào kho…","Moving to vault…"},
   {"Đã xóa thẳng {0} tệp ({1}). Bỏ qua vì đang dùng: {2}. Lỗi: {3}.","Deleted {0} files directly ({1}). Skipped because in use: {2}. Errors: {3}."},
   {"Đã chuyển vào kho {0} tệp ({1}). Bỏ qua vì đang dùng: {2}. Lỗi: {3}.","Moved {0} files to the vault ({1}). Skipped because in use: {2}. Errors: {3}."},{" Bản sao lưu: {0}."," Backups: {0}."},
   {"\r\n\r\nLỗi đầu tiên:\r\n","\r\n\r\nFirst errors:\r\n"},{"\r\n\r\nCó thể khôi phục hoặc xóa vĩnh viễn trong tab Kho khôi phục.","\r\n\r\nYou can restore or permanently delete them in the Recovery Vault tab."},{"Kết quả dọn rác","Junk cleaning result"},
   {"Chọn một quy tắc để xem tệp.","Select a rule to view its files."},{"Tệp sẽ dọn — ","Files to clean — "},{"Sửa lần cuối","Last modified"},
   {"Hiển thị 2.000 tệp lớn nhất trong {0} tệp.","Showing the 2,000 largest of {0} files."},{"Chưa xem trước hoặc không có tệp đủ điều kiện.","Not previewed yet, or no file qualifies."},{"Danh sách chỉ để xem; chưa có gì bị thay đổi.","Read-only list; nothing has changed."},

   {"Không đọc được quy tắc dọn rác: ","Could not read junk rules: "},{"Đã nạp {0} quy tắc dọn rác từ {1}.","Loaded {0} junk rules from {1}."},{"Dọn rác: đang xem trước {0} quy tắc (chỉ đọc).","Junk: previewing {0} rules (read-only)."},
   {"Dọn rác: xem trước xong — {0} tệp, {1}, {2} nhóm bị khóa.","Junk: preview done — {0} files, {1}, {2} groups locked."},{"Dọn rác: bắt đầu xóa thẳng {0} tệp trong {1} nhóm.","Junk: deleting {0} files in {1} groups directly."},{"Dọn rác: bắt đầu chuyển vào kho {0} tệp trong {1} nhóm.","Junk: moving {0} files in {1} groups to the vault."},
   {"Dọn rác: ","Junk: "},{"Dọn rác lỗi: ","Junk error: "},
   // Junk rule groups and names (junk-rules.json)
   {"Hệ thống","System"},{"Trình duyệt","Browsers"},{"Bộ đệm","Caches"},{"Rác hệ thống (cần quyền quản trị)","System junk (administrator required)"},
   {"Tệp tạm của tài khoản (%TEMP%)","User temporary files (%TEMP%)"},{"Tệp tạm của Windows (C:\\Windows\\Temp)","Windows temporary files (C:\\Windows\\Temp)"},
   {"Tệp dump khi ứng dụng gặp lỗi (CrashDumps)","Application crash dumps (CrashDumps)"},{"Báo cáo lỗi Windows của tài khoản (WER)","User Windows Error Reporting (WER)"},
   {"Báo cáo lỗi Windows toàn máy (ProgramData\\WER)","Machine-wide Windows Error Reporting (ProgramData\\WER)"},{"Bộ đệm ảnh thu nhỏ của Explorer","Explorer thumbnail cache"},
   {"Google Chrome — bộ đệm","Google Chrome — cache"},{"Microsoft Edge — bộ đệm","Microsoft Edge — cache"},{"Brave — bộ đệm","Brave — cache"},{"Mozilla Firefox — bộ đệm","Mozilla Firefox — cache"},
   {"Bộ đệm web cũ của Windows (INetCache)","Legacy Windows web cache (INetCache)"},{"Bộ đệm shader của card đồ họa (DirectX / NVIDIA / AMD)","GPU shader cache (DirectX / NVIDIA / AMD)"},
   {"Gói Windows Update đã tải (SoftwareDistribution\\Download)","Downloaded Windows Update packages (SoftwareDistribution\\Download)"},{"Nhật ký bảo trì thành phần Windows (Logs\\CBS)","Component servicing logs (Logs\\CBS)"},
   {"Tệp dump lỗi hệ thống (Minidump, LiveKernelReports)","System crash dumps (Minidump, LiveKernelReports)"},{"Nhật ký cài đặt / nâng cấp Windows (Panther)","Windows setup / upgrade logs (Panther)"},
   {"Thành phần ActiveX/Java cũ (Downloaded Program Files)","Legacy ActiveX/Java components (Downloaded Program Files)"},
   // Junk rule descriptions
   {"Tệp tạm do ứng dụng để lại trong thư mục Temp của tài khoản hiện tại. Bỏ qua tệp mới hơn 24 giờ và tệp đang được mở.","Temporary files applications leave in the current user's Temp folder. Files newer than 24 hours and open files are skipped."},
   {"Thư mục Temp dùng chung của hệ thống. Cần quyền quản trị để đọc và dọn đầy đủ.","The shared system Temp folder. Administrator rights are needed to read and clean it fully."},
   {"Bản ghi bộ nhớ Windows tạo khi ứng dụng bị treo; chỉ hữu ích khi đang gỡ lỗi.","Memory dumps Windows writes when an application crashes; only useful while debugging."},
   {"Hàng đợi và kho báo cáo lỗi Windows Error Reporting trong hồ sơ người dùng.","Windows Error Reporting queue and archive in the user profile."},
   {"Hàng đợi báo cáo lỗi toàn máy. Cần quyền quản trị.","Machine-wide error report queue. Administrator rights required."},
   {"thumbcache_*.db và iconcache_*.db. Windows tạo lại khi cần; tệp đang được Explorer giữ sẽ bị bỏ qua.","thumbcache_*.db and iconcache_*.db. Windows rebuilds them on demand; files held open by Explorer are skipped."},
   {"Cache, Code Cache và GPUCache của mọi hồ sơ Chrome. Không đụng đến lịch sử, cookie, mật khẩu. Chỉ dọn khi Chrome đã đóng.","Cache, Code Cache and GPUCache of every Chrome profile. History, cookies and passwords are untouched. Cleaned only while Chrome is closed."},
   {"Cache, Code Cache và GPUCache của mọi hồ sơ Edge. Chỉ dọn khi Edge đã đóng (kể cả tiến trình nền).","Cache, Code Cache and GPUCache of every Edge profile. Cleaned only while Edge is closed (including background processes)."},
   {"Cache, Code Cache và GPUCache của mọi hồ sơ Brave. Chỉ dọn khi Brave đã đóng.","Cache, Code Cache and GPUCache of every Brave profile. Cleaned only while Brave is closed."},
   {"Thư mục cache2 của mọi hồ sơ Firefox. Không đụng đến lịch sử, cookie, mật khẩu. Chỉ dọn khi Firefox đã đóng.","The cache2 folder of every Firefox profile. History, cookies and passwords are untouched. Cleaned only while Firefox is closed."},
   {"Cache của Internet Explorer / WebView / Office web content. Không chứa mật khẩu hay lịch sử.","Cache of Internet Explorer / WebView / Office web content. Holds no passwords or history."},
   {"Shader đã biên dịch; trình điều khiển tự tạo lại khi cần. Game có thể giật nhẹ ở lần chạy đầu sau khi dọn.","Compiled shaders; the driver rebuilds them on demand. Games may stutter briefly on the first run after cleaning."},
   {"Bộ cài cập nhật Windows đã tải về và đã áp dụng. Windows tự tải lại nếu cần. Chỉ dọn tệp cũ hơn 7 ngày để không cắt ngang cập nhật đang chạy.","Downloaded and already-applied Windows Update packages. Windows re-downloads them if needed. Only files older than 7 days are cleaned so a running update is never interrupted."},
   {"Nhật ký của Component Based Servicing, có thể phình tới nhiều GB. Chỉ dọn tệp cũ hơn 7 ngày; nhật ký hiện tại được giữ.","Component Based Servicing logs, which can grow to several GB. Only files older than 7 days are cleaned; the current log is kept."},
   {"Bản ghi bộ nhớ Windows tạo khi màn hình xanh hoặc lỗi kernel; chỉ cần khi đang gỡ lỗi.","Memory dumps Windows writes after a blue screen or kernel error; only needed while debugging."},
   {"Nhật ký do trình cài đặt Windows để lại sau khi nâng cấp phiên bản. Chỉ dọn tệp cũ hơn 7 ngày.","Logs left by Windows Setup after a version upgrade. Only files older than 7 days are cleaned."},
   {"Thư mục kế thừa của Internet Explorer; hầu như luôn trống hoặc chỉ còn tàn dư.","Legacy Internet Explorer folder; almost always empty or holding remnants only."},
   // Network tab: application view
   {"Hoạt động","Activity"},{"Kết nối","Connections"},{"Đã kết nối","Established"},{"Lắng nghe","Listening"},{"kết nối","connections"},
   {"Đang gửi","Sending"},{"Đang nhận","Receiving"},{"Gửi và nhận","Sending and receiving"},{"Không hoạt động","Idle"},{"Gửi đi","Out"},{"Nhận về","In"},
   {"Hiện tất cả kết nối","Show all connections"},{"Kết nối của tất cả ứng dụng — bấm một ứng dụng ở bảng trên để lọc","Connections of all applications — click an application above to filter"},{"Kết nối của: {0}","Connections of: {0}"},
   {"Chọn một ứng dụng ở bảng trên để xem các kết nối của nó.","Select an application above to see its connections."},{"Ứng dụng đã chọn không còn kết nối nào.","The selected application has no connections left."},
