   {"Kết thúc tiến trình (PID {0})","End process (PID {0})"},{"Dịch vụ: đã kết thúc tiến trình PID {0} của {1}.","Services: ended process PID {0} of {1}."},
   {"Sao chép tên dịch vụ","Copy service name"},
   {"(dịch vụ theo tài khoản; Windows tự tạo lại khi đăng nhập)","(per-user service; Windows recreates it at sign-in)"},
   {"Thành phần của Windows (chạy từ thư mục Windows). Không có mô tả thêm.","Windows component (runs from the Windows folder). No further description."},
   {"Dịch vụ nền của {0}. Ứng dụng cài kèm để chạy ngầm dù bạn chưa mở nó; dừng thường an toàn, ứng dụng sẽ tự bật lại khi cần.","Background service of {0}. Installed alongside the app to run even when the app is closed; usually safe to stop, the app restarts it when needed."},
   {"Cốt lõi — không dừng","Core — do not stop"},{"Windows — dừng khi hiểu rõ","Windows — stop only if you know why"},{"Tùy chọn — tắt được nếu không dùng","Optional — disable if unused"},{"Bên thứ ba — dừng an toàn","Third-party — safe to stop"},
   {"Windows cần dịch vụ này để chạy ổn định; Tweek Pro không cho dừng hay vô hiệu hóa.","Windows needs this service to run reliably; Tweek Pro does not allow stopping or disabling it."},
   {"Thuộc Windows nhưng không thiết yếu. Dừng có thể làm mất một tính năng; vô hiệu hóa được lưu vào Kho để bật lại.","Part of Windows but not essential. Stopping may lose a feature; disabling is saved to the Vault so you can re-enable it."},
   {"Tính năng tùy chọn của Windows. Nếu bạn không dùng, tắt an toàn để tiết kiệm RAM và thời gian khởi động.","Optional Windows feature. If you do not use it, disabling is safe and saves RAM and boot time."},
   {"Do ứng dụng bên thứ ba cài. Dừng an toàn; nếu vô hiệu hóa, ứng dụng đó có thể mất cập nhật tự động.","Installed by a third-party app. Safe to stop; if disabled, that app may lose automatic updates."},
   {"Bảo mật","Security"},{"Cập nhật","Updates"},{"Màn hình & âm thanh","Display & audio"},{"Tùy chọn","Optional"},{"Quyền riêng tư","Privacy"},{"Game","Games"},{"Máy chủ","Server"},{"Điều khiển từ xa","Remote control"},{"Thiết bị ngoại vi","Peripherals"},{"Bản quyền","Licensing"},{"Phụ trợ","Helper"},
   // AI assistant tab
   {"Trợ lý AI","AI Assistant"},{"Nhà cung cấp","Provider"},{"Lưu khóa","Save key"},{"Kiểm tra kết nối","Test connection"},
   {"Điểm cuối API (tùy chọn, cho máy chủ tương thích)","API endpoint (optional, for compatible servers)"},
   {"Cho phép AI thực hiện thao tác thay đổi (mỗi lần đều hỏi xác nhận)","Allow the AI to perform system-changing actions (each one asks for confirmation)"},
   {"Khóa API được mã hóa bằng Windows DPAPI theo tài khoản của bạn và chỉ gửi tới nhà cung cấp bạn chọn. AI đọc dữ liệu qua các công cụ chỉ đọc; mọi thao tác thay đổi (dừng dịch vụ, kết thúc tiến trình, tắt khởi động, gỡ ứng dụng) đều hiện hộp xác nhận và tuân thủ các giới hạn an toàn của Tweek Pro.","The API key is encrypted with Windows DPAPI for your account and only sent to the provider you choose. The AI reads data through read-only tools; every system-changing action (stop service, end process, disable startup, uninstall) shows a confirmation dialog and follows Tweek Pro's safety limits."},
   {"Máy tôi có gì đang chạy nền tốn RAM và tắt được không?","What is running in the background eating RAM, and can I turn it off?"},
   {"Dịch vụ nào của bên thứ ba có thể dừng an toàn?","Which third-party services are safe to stop?"},
   {"Ứng dụng nào đang dùng mạng nhiều nhất?","Which application is using the network the most?"},
   {"Có bao nhiêu rác có thể dọn?","How much junk can be cleaned?"},{"Mục khởi động nào nên tắt?","Which startup entries should I disable?"},
