   {"Sẵn sàng — {0}, model {1}. Enter để gửi; Shift+Enter xuống dòng.","Ready — {0}, model {1}. Enter sends; Shift+Enter adds a line."},
   {"Nhập API key của Anthropic (Claude) hoặc OpenAI (GPT/Codex) rồi bấm Lưu khóa để bắt đầu.","Enter an Anthropic (Claude) or OpenAI (GPT/Codex) API key and click Save key to begin."},
   {"Trợ lý AI: đã xóa API key.","AI assistant: API key removed."},{"Trợ lý AI: đã lưu khóa cho {0} ({1}).","AI assistant: key saved for {0} ({1})."},
   {"Chưa nhập API key.","No API key entered."},{"API key chứa khoảng trắng hoặc ký tự lạ — hãy dán lại.","The API key contains whitespace or unusual characters — paste it again."},
   {"Key của Anthropic bắt đầu bằng sk-ant-.","Anthropic keys start with sk-ant-."},{"Key của OpenAI bắt đầu bằng sk-.","OpenAI keys start with sk-."},
   {" API key không hợp lệ hoặc đã bị thu hồi."," The API key is invalid or revoked."},{" Hết hạn mức hoặc gửi quá nhanh — thử lại sau."," Quota exhausted or rate limited — try again later."},{" Tên model không tồn tại — kiểm tra ô Model."," Unknown model name — check the Model box."},
   {"Đang kiểm tra kết nối…","Testing connection…"},{"Kết nối thành công — model trả lời: \"{0}\" ({1} token vào / {2} ra).","Connected — the model replied \"{0}\" ({1} tokens in / {2} out)."},
   {"Trợ lý AI: kiểm tra kết nối thành công.","AI assistant: connection test succeeded."},{"Kết nối thất bại: ","Connection failed: "},{"Trợ lý AI: kết nối thất bại — ","AI assistant: connection failed — "},
   {"Xin chào! Tôi là trợ lý của Tweek Pro. Hỏi tôi về máy này — ứng dụng, dịch vụ, mạng, rác, khởi động — hoặc nhờ tôi thao tác; mọi thay đổi đều hỏi bạn xác nhận trước.","Hello! I am Tweek Pro's assistant. Ask me about this PC — applications, services, network, junk, startup — or ask me to act; every change asks you for confirmation first."},
   {"Đang hỏi model…","Asking the model…"},{"Xong — {0} token vào / {1} ra trong phiên này.","Done — {0} tokens in / {1} out this session."},{"Lỗi: ","Error: "},{"Trợ lý AI: ","AI assistant: "},
   {"Bạn","You"},{"Công cụ AI","Tool"},{"Lỗi","Error"},
   {"Trợ lý AI muốn thực hiện:\r\n\r\n{0}\r\n\r\nCho phép? Tweek Pro vẫn áp dụng mọi giới hạn an toàn (dịch vụ/tiến trình cốt lõi bị từ chối, thay đổi được lưu vào Kho khôi phục khi có thể).","The AI assistant wants to run:\r\n\r\n{0}\r\n\r\nAllow it? Tweek Pro still enforces every safety limit (core services/processes are refused, changes are saved to the Recovery Vault when possible)."},
   {"Trợ lý đã gọi công cụ quá nhiều vòng và dừng lại. Hãy hỏi cụ thể hơn.","The assistant called tools for too many rounds and stopped. Please ask something more specific."},
   {"công cụ không tồn tại","unknown tool"},{"bị chặn — thao tác thay đổi đang tắt","blocked — system-changing actions are off"},{"người dùng từ chối","declined by the user"},{"xong","done"},{"lỗi","error"},
   {"Trợ lý AI: đã {0} dịch vụ {1}.","AI assistant: {0} service {1}."},{"dừng và vô hiệu hóa","stopped and disabled"},{"dừng","stopped"},
   {"Trợ lý AI: đã khởi động dịch vụ {0}.","AI assistant: started service {0}."},{"Trợ lý AI: đã kết thúc tiến trình {0} (PID {1}).","AI assistant: ended process {0} (PID {1})."},{"Trợ lý AI: đã tắt mục khởi động {0}.","AI assistant: disabled startup entry {0}."},
   {"Có 4 dịch vụ bên thứ ba đang chạy, dừng đều an toàn:\r\n• Adobe Acrobat Update Service (AdobeARMservice) — 3 MB, trình cập nhật; Acrobat vẫn tự cập nhật khi mở.\r\n• MySQL80 — 412 MB RAM, máy chủ cơ sở dữ liệu; dừng nếu bạn không đang lập trình.\r\n• Zoom Sharing Service (ZoomCptService) — 12 MB, Zoom tự bật lại khi cần.\r\n• Brave Elevation Service — đã dừng, chỉ chạy khi cập nhật.\r\nBạn muốn tôi dừng MySQL80 để giải phóng 412 MB không? Tôi sẽ hỏi xác nhận trước khi làm.","4 third-party services are running and all are safe to stop:\r\n• Adobe Acrobat Update Service (AdobeARMservice) — 3 MB, an updater; Acrobat still updates itself when opened.\r\n• MySQL80 — 412 MB RAM, a database server; stop it when you are not developing.\r\n• Zoom Sharing Service (ZoomCptService) — 12 MB, Zoom restarts it when needed.\r\n• Brave Elevation Service — already stopped, runs only during updates.\r\nShall I stop MySQL80 to free 412 MB? I will ask for confirmation first."},
   // Applications tab details
   {"Toàn máy","All users"},{"Tài khoản","This account"},{"Không rõ","Unknown"},{"{0} ứng dụng hiển thị  /  {1} ứng dụng trên máy","{0} shown  /  {1} installed"},
   {"Chọn một ứng dụng để xem thông tin.","Select an application to see its details."},{"Chọn một ứng dụng để xem thông tin. Dùng ô tìm kiếm để lọc theo tên hoặc nhà phát hành.","Select an application to see its details. Use the search box to filter by name or publisher."},
   {"Thư mục: ","Folder: "},{"Chưa được ứng dụng khai báo","Not declared by the application"},{"Ngày do bộ cài cung cấp, có thể là ngày cập nhật. Giá trị gốc: ","Date reported by the installer; may be the last update. Raw value: "},{"không có","none"},
   {"Mở trình gỡ chính thức lần lượt cho {0} ứng dụng?\r\n\r\n{1}\r\n\r\nTrình gỡ có thể xóa dữ liệu và yêu cầu quyền quản trị. Kho Tweek Pro chỉ khôi phục phần dọn sau đó, không hoàn tác trình gỡ.","Open the official uninstaller for {0} application(s), one after another?\r\n\r\n{1}\r\n\r\nThe uninstaller may delete data and ask for administrator rights. Tweek Pro's vault only restores the cleanup done afterwards; it cannot undo the uninstaller."},
   {"Tiếp tục gỡ {0}?\r\nChọn No để dừng hàng đợi.","Continue uninstalling {0}?\r\nChoose No to stop the queue."},
   // Review fixes
   {"Không kết nối được tới máy chủ API: ","Could not reach the API server: "},{"Máy chủ API không trả lời trong 120 giây.","The API server did not answer within 120 seconds."},
   {"Điểm cuối API không phải URL hợp lệ.","The API endpoint is not a valid URL."},{"Điểm cuối API phải dùng https:// (http:// chỉ cho localhost) để không lộ khóa.","The API endpoint must use https:// (http:// only for localhost) so the key is not exposed."},
   {"Model không trả lời nội dung nào","The model returned no content"},{"Trợ lý AI: không mã hóa được khóa bằng DPAPI — ","AI assistant: could not encrypt the key with DPAPI — "},
   {"Windows không mã hóa được khóa (DPAPI). Khóa chưa được lưu.","Windows could not encrypt the key (DPAPI). The key was not saved."},{"không xác định được tiến trình","process name unknown"},
   {"Chưa được ứng dụng khai báo thư mục cài","Install folder not declared by the application"},{"Ngày bộ cài khai báo: ","Date reported by the installer: "},{"Không có","None"},{"không phải đường dẫn tệp","not a file path"},
   {" (MSI im lặng)"," (silent MSI)"},
   {"API key (không cần)","API key (optional)"},
   {"Chưa chọn model cục bộ — bấm \"Tải danh sách model\" rồi chọn một model đã nạp trong LM Studio/Ollama.","No local model selected. Click \"Load models\" and select a model loaded in LM Studio/Ollama."},
   {"Chưa chọn model cục bộ.","No local model selected."},
   {"Chỉ máy chủ tương thích OpenAI mới hỗ trợ liệt kê model.","Only OpenAI-compatible servers support listing models."},
   {"Chỉ đọc — không thay đổi gì","Read only — no changes"},
   {"Chọn LM Studio/Ollama để dùng model cục bộ, hoặc Claude/OpenAI bằng API key. Dữ liệu gửi tới máy chủ bạn chọn. Kho khôi phục lưu phần dọn còn sót, không hoàn tác trình gỡ ứng dụng. Chế độ Tự động chỉ dùng khi bạn chọn; giới hạn bảo vệ hệ thống luôn có hiệu lực.","Choose LM Studio/Ollama for local models, or Claude/OpenAI with an API key. Data goes to your selected server. The vault backs up leftover cleanup, not the official uninstall. Automatic mode requires your selection; system protections always apply."},
   {"Hỏi xác nhận trước mỗi thao tác","Confirm each action"},
   {"Không bao giờ xóa gốc ổ đĩa.","Drive roots can never be removed."},
   {"Không kết nối được tới máy chủ LLM cục bộ — hãy mở LM Studio/Ollama và bật Local Server: ","Cannot reach the local LLM server. Open LM Studio/Ollama and enable its server: "},
   {"Không tải được danh sách model: ","Could not load models: "},
   {"Lưu cấu hình","Save settings"},
   {"Model cục bộ: ","Local model: "},
   {"Máy chủ API không trả lời trong {0} giây.","The API server did not respond within {0} seconds."},
   {"Máy chủ LLM cục bộ phải nằm ở localhost hoặc trong mạng nội bộ (10.x, 172.16–31.x, 192.168.x).","The local LLM server must use localhost or a private network address (10.x, 172.16–31.x, 192.168.x)."},
   {"Máy chủ không có model nào — hãy nạp (load) một model trong LM Studio hoặc `ollama pull` trước.","No models found. Load a model in LM Studio or use `ollama pull` first."},
   {"Mở LM Studio/Ollama, nạp một model, bấm \"Tải danh sách model\" rồi chọn model và Lưu cấu hình.","Open LM Studio/Ollama, load a model, click \"Load models\", select it and save settings."},
   {"Nhập API key của Anthropic (Claude) hoặc OpenAI (GPT/Codex) rồi bấm Lưu cấu hình để bắt đầu. Hoặc chọn LM Studio/Ollama để dùng model trên máy, không cần key.","Enter an Anthropic (Claude) or OpenAI (GPT/Codex) API key and save settings. Or choose LM Studio/Ollama to use a local model without a key."},
   {"Nằm trong thư mục Windows (System32, WinSxS…) — Tweek Pro không bao giờ xóa.","Inside the Windows directory (System32, WinSxS…). Tweek Pro never removes this."},
   {"Quyền thao tác của AI","AI action permissions"},
   {"Sẵn sàng — {0}, model {1}, chế độ: {2}. Enter để gửi; Shift+Enter xuống dòng.","Ready — {0}, model {1}, mode: {2}. Enter to send; Shift+Enter for a new line."},
   {"Trợ lý AI: chưa dọn được ","AI assistant: could not clean "},
   {"Trợ lý AI: dọn rác {0} quy tắc vào Kho khôi phục.","AI assistant: cleaning {0} junk rules into the Recovery Vault."},
   {"Trợ lý AI: mở trình gỡ {0}{1}.","AI assistant: opening the uninstaller for {0}{1}."},
   {"Trợ lý AI: quét phần còn sót của {0} ứng dụng ({1}).","AI assistant: scanning leftovers for {0} applications ({1})."},
   {"Trợ lý AI: từ chối xóa ","AI assistant: refused to remove "},
   {"Trợ lý AI: đã lưu cấu hình {0}, model {1}, chế độ {2}.","AI assistant: saved {0}, model {1}, mode {2}."},
   {"Trợ lý AI: đã sao lưu và dọn ","AI assistant: backed up and cleaned "},
   {"Tải danh sách model","Load models"},
   {"Tự động thực hiện, không hỏi lại","Automatic actions, without asking again"},
   {"Xin chào! Tôi là trợ lý của Tweek Pro. Hỏi tôi về máy này hoặc ra lệnh trực tiếp — \"gỡ Zoom và dọn sạch phần còn sót\", \"kill dịch vụ MySQL\", \"dọn rác\" — tôi sẽ làm ngay và báo lại kết quả. Phần dọn còn sót được sao lưu; kho không hoàn tác trình gỡ chính thức; thư mục Windows/System32 luôn được bảo vệ.","Hello! I am the Tweek Pro assistant. Ask about this PC or give an instruction such as \"uninstall Zoom and clean its leftovers\", \"stop MySQL\" or \"clean junk\". I will act and report the result. Leftover cleanup is backed up; the vault cannot undo the official uninstall. Windows/System32 remain protected."},
   {"\"{0}\" là thư mục gốc hệ thống/người dùng, không được xóa.","\"{0}\" is a system/user root folder and cannot be removed."},
   {"quét nhanh","quick scan"},
   {"quét sâu","deep scan"},
   {"tự động thực hiện","running automatically"},
   {"vẫn còn đăng ký cài đặt; không tự quét/dọn.","still registered as installed; automatic scan/cleanup skipped."},
   {"Đang tải danh sách model…","Loading models…"},
   {"Đi qua thư mục hệ thống \"{0}\" — bị chặn.","Path passes through system folder \"{0}\" — blocked."},
   {"Điểm cuối API","API endpoint"},
   {"Đã tải {0} model từ {1}. Chọn model rồi bấm Lưu cấu hình.","Loaded {0} models from {1}. Select a model and save settings."},
   {"Đường dẫn không hợp lệ hoặc không phải đường dẫn tuyệt đối trên ổ đĩa.","Invalid path or not an absolute drive path."},
   {"Đường dẫn trống.","Empty path."},
   {"đã bỏ đăng ký.","no longer registered."},
   {"Model này không hỗ trợ thao tác. Hãy chọn model có hỗ trợ gọi công cụ.","This model cannot perform actions. Select a model with tool-calling support."},
   {"Model này không hỗ trợ gọi công cụ; chỉ trả lời hướng dẫn, không thao tác trên máy.","This model does not support tool calling. It can give guidance but cannot operate this PC."},
   // Applications / Leftovers / Vault / Log tab runtime texts (App.cs, Presentation.cs)
   {"LỖI: ","ERROR: "},{"Đã lưu settings.json.","settings.json saved."},{"Không đọc được lịch sử: ","Could not read history: "},
   {"Nhật ký phiên hiện tại. Tệp nhật ký xoay vòng theo ngày trong {0} (giữ {1} ngày). Cài đặt: {2}.","Current session log. Log files rotate daily in {0} (kept {1} days). Settings: {2}."},
   {"Đang xử lý. Hãy chờ thao tác hiện tại hoàn tất.","Working. Please wait for the current operation to finish."},
   {"Không đọc được danh sách ứng dụng","Could not read the application list"},
   {"Không đọc được danh sách ứng dụng.\r\n{0}\r\n\r\nBấm Làm mới để thử lại. Nếu khóa HKLM bị chặn, chạy Tweek Pro với quyền quản trị cùng tài khoản Windows.","Could not read the application list.\r\n{0}\r\n\r\nClick Refresh to try again. If the HKLM key is blocked, run Tweek Pro as administrator with the same Windows account."},
   {"Không có ứng dụng khớp với «{0}».\r\nThử từ khóa khác hoặc xóa ô tìm kiếm.","No application matches «{0}».\r\nTry another keyword or clear the search box."},
   {"Đã đọc {0} ứng dụng desktop. Chưa bao gồm toàn bộ ứng dụng Microsoft Store.","Read {0} desktop applications. Microsoft Store apps are not fully included."},
   {"Chọn ứng dụng muốn gỡ.","Select the application(s) to uninstall."},{"Mở trình gỡ: ","Opening uninstaller: "},
   {"Trình gỡ của {0} đã kết thúc tiến trình chính nhưng ứng dụng vẫn còn đăng ký. Nếu có cửa sổ gỡ khác, hãy hoàn tất hoặc hủy rồi nhấn OK. Nếu cần khởi động lại, có thể quét lại lịch sử sau đó.","The uninstaller of {0} ended its main process but the application is still registered. If another uninstall window is open, finish or cancel it, then press OK. If a restart is required, you can rescan the history later."},
   {"Kiểm tra trình gỡ","Uninstaller check"},{"đã bỏ đăng ký; mở cửa sổ quét phần còn sót.","registration removed; opening the leftover scan window."},
   {"Không hoàn tất thao tác","Operation not completed"},{"Đã kết thúc hàng đợi. Còn {0} mục chờ duyệt ở tab Phần còn sót.","Queue finished. {0} items await review in the Leftovers tab."},
   {": tìm thấy {0} mục, đã xóa {1}, lỗi {2}, còn {3} mục chờ duyệt.",": found {0} items, deleted {1}, {2} errors, {3} still awaiting review."},
   {"Chọn một dòng ứng dụng trước.","Select an application row first."},{"Chưa có lịch sử. Hãy chọn ứng dụng và quét hoặc gỡ trước.","No history yet. Select an application and scan or uninstall it first."},
   {"Đang quét {0} ứng dụng…","Scanning {0} applications…"},{"Tìm thấy {0} mục cần duyệt. Không tìm thấy không có nghĩa đã sạch toàn bộ.","Found {0} items to review. Finding nothing does not mean everything is clean."},
   {"Tìm thấy: {0} mục  •  Đã chọn: {1}  •  Xóa sẽ lưu bản khôi phục trước.","Found: {0} items  •  Selected: {1}  •  Deleting saves a recovery copy first."},
   {"CHỈ XEM • ","VIEW ONLY • "},{"CHỈ XEM: ","VIEW ONLY: "},{"Chỉ xem","View only"},{"Thư mục","Folder"},{"Giá trị Registry","Registry value"},{"Khóa Registry","Registry key"},{"Rác","Junk"},{"Bản trùng","Duplicate"},{"AppCare (cũ)","AppCare (legacy)"},
   {"Chọn một mục để xem.","Select an item to inspect."},{"\r\n\r\nChỉ xem: không tự xóa mục này.","\r\n\r\nView only: this item is never deleted automatically."},{"\r\n\r\nKiểm tra đúng khóa hoặc giá trị trước khi chọn dọn.","\r\n\r\nVerify the key or value before selecting it for cleanup."},{"Chi tiết mục còn sót","Leftover details"},
   {"Đánh dấu những mục đã kiểm tra và muốn dọn.","Check the items you have reviewed and want to clean."},
   {"Sao lưu và dọn {0} mục đã đánh dấu?\r\n\r\n{1}\r\n\r\nCác mục có thể chứa cài đặt, dự án hoặc dữ liệu cá nhân. Chỉ tiếp tục khi đã kiểm tra. File được chuyển vào kho nên chưa giải phóng dung lượng ổ đĩa. Registry được lưu giá trị và khóa con, không lưu quyền ACL.","Back up and clean {0} checked items?\r\n\r\n{1}\r\n\r\nItems may hold settings, projects or personal data. Continue only after reviewing them. Files move to the vault, so no disk space is freed yet. Registry keys are saved with values and subkeys, not ACL permissions."},
   {"Đang sao lưu: ","Backing up: "},{"Đã sao lưu và dọn: ","Backed up and cleaned: "},{"Giữ lại / cần kiểm tra ","Kept / needs review "},{"Mục chưa dọn xong","Item not cleaned"},{"Không hẹn xóa được ","Could not schedule deletion for "},
   {"Đã dọn và sao lưu: {0} mục file/thư mục, {1} mục Registry.","Cleaned and backed up: {0} file/folder items, {1} Registry items."},{" Hẹn xóa khi khởi động lại: {0} mục."," Scheduled for deletion at reboot: {0} items."},{" Chưa dọn: {0} mục. Còn hiển thị: {1} mục."," Not cleaned: {0} items. Still listed: {1} items."},
   {"\r\n\r\nCó thể khôi phục trong Kho khôi phục. File trong kho vẫn chiếm dung lượng.","\r\n\r\nYou can restore them from the Recovery Vault. Files in the vault still use disk space."},{"Kết quả dọn","Cleanup result"},
   {"Chọn một bản sao lưu.","Select a backup."},{"Mục này đã khôi phục.","This item has already been restored."},
   {"Khôi phục về vị trí gốc?\r\n{0}\r\n\r\nKhông ghi đè nếu đích đã tồn tại. Nếu lần dọn trước bị gián đoạn, kiểm tra cả vị trí gốc và kho.","Restore to the original location?\r\n{0}\r\n\r\nExisting targets are never overwritten. If the previous cleanup was interrupted, check both the original location and the vault."},
   {"Đã khôi phục: ","Restored: "},{"Đánh dấu (tick) các bản sao lưu muốn xóa vĩnh viễn.","Check (tick) the backups to delete permanently."},{"đã đánh dấu","checked"},{"Kho trống.","The vault is empty."},
   {"Không có bản sao lưu nào đủ tuổi theo lựa chọn.","No backup is old enough for the chosen age."},{"cũ hơn {0} ngày","older than {0} days"},
   {"XÓA VĨNH VIỄN {0} bản sao lưu {1} ({2})?\r\n\r\n{3}","PERMANENTLY DELETE {0} backups {1} ({2})?\r\n\r\n{3}"},{"\r\n… và {0} mục khác","\r\n… and {0} more"},
   {"\r\n\r\nCẢNH BÁO: {0} bản chưa khôi phục sẽ mất vĩnh viễn — không thể hoàn tác các lần dọn tương ứng nữa.","\r\n\r\nWARNING: {0} unrestored backups will be lost forever — the corresponding cleanups can no longer be undone."},{"\r\n\r\nThao tác này không thể hoàn tác.","\r\n\r\nThis cannot be undone."},
   {"Đã xóa vĩnh viễn bản sao lưu {0} ({1}).","Permanently deleted backup {0} ({1})."},{"Không xóa được {0}: {1}","Could not delete {0}: {1}"},{"Đã xóa vĩnh viễn {0} bản sao lưu, giải phóng {1}. Lỗi: {2}.","Permanently deleted {0} backups, freed {1}. Errors: {2}."},{"Kết quả dọn kho","Vault purge result"},
   {"Đã xuất danh sách: ","List exported: "},{"Đã xuất báo cáo: ","Report exported: "},
   // Leftover scan window (ScanWindow.cs)
   {"Quét phần còn sót","Leftover scan"},{"Quét sâu","Deep scan"},{"Quét nhanh","Quick scan"},{"Quét sâu: ","Deep scan: "},{"Quét nhanh: ","Quick scan: "},{"Đang chuẩn bị quét…","Preparing scan…"},
   {"Đang sao lưu và xóa. Hãy chờ thao tác hoàn tất.","Backing up and deleting. Please wait for the operation to finish."},
   {"Còn {0} ghi chú được rút gọn.","{0} more notes were truncated."},{"LỖI quét: ","Scan ERROR: "},{"Đang tính dung lượng các mục tìm thấy…","Measuring the size of found items…"},
   {"{0} thư mục đã duyệt  •  {1} ghi chú (xem Nhật ký)","{0} folders visited  •  {1} notes (see Log)"},{"{0} thư mục đã duyệt  •  {1} mục tìm thấy","{0} folders visited  •  {1} items found"},
   {"Cửa sổ quét: {0} mục, {1} thư mục đã duyệt, {2} ghi chú.","Scan window: {0} items, {1} folders visited, {2} notes."},{"Chờ duyệt","Awaiting review"},
   {"Hãy đánh dấu những mục đã kiểm tra và muốn xóa.","Check the items you have reviewed and want to delete."},
   {"Sao lưu và xóa {0} mục đã chọn{1}?\r\n\r\n{2}\r\n\r\nFile và thư mục được chuyển vào Kho khôi phục trên cùng ổ đĩa. Registry được lưu giá trị và khóa con trước khi xóa.","Back up and delete {0} selected items{1}?\r\n\r\n{2}\r\n\r\nFiles and folders move to the Recovery Vault on the same drive. Registry keys are saved with values and subkeys before deletion."},
   {" (khoảng {0})"," (about {0})"},{"Xác nhận xóa","Confirm deletion"},{"Đang sao lưu và xóa {0}/{1}","Backing up and deleting {0}/{1}"},{"Đã xóa (có sao lưu)","Deleted (backed up)"},{"Đã sao lưu và xóa: ","Backed up and deleted: "},{"Giữ lại ","Kept "},
   {"Hoàn tất xóa.  Còn {0} mục chờ duyệt.","Deletion finished.  {0} items still await review."},{"Đã xóa {0} mục và lưu bản khôi phục","Deleted {0} items and saved recovery copies"},
   {"; {0} mục chưa xóa được — di chuột lên dòng màu đỏ để xem lý do.","; {0} items could not be deleted — hover a red row for the reason."},{" Có thể khôi phục trong tab Kho khôi phục."," You can restore them in the Recovery Vault tab."},
   {"Không hoàn tất quét.\r\n{0}\r\n\r\nĐóng cửa sổ rồi quét lại từ tab Phần còn sót.","Scan not completed.\r\n{0}\r\n\r\nClose this window and scan again from the Leftovers tab."},{"Lỗi không xác định.","Unknown error."},{"Không hoàn tất quét: ","Scan not completed: "},
   {"Chưa tìm thấy mục nào trước khi dừng.\r\nCó thể quét lại từ tab Phần còn sót.","Nothing was found before the scan stopped.\r\nYou can scan again from the Leftovers tab."},
   {"Không tìm thấy phần còn sót theo các quy tắc hiện tại.\r\nĐiều này không bảo đảm hệ thống đã sạch hoàn toàn.","No leftovers found with the current rules.\r\nThis does not guarantee the system is completely clean."},
   {"Quét gặp lỗi: {0}. Kết quả bên dưới có thể chưa đầy đủ.","The scan hit an error: {0}. The results below may be incomplete."},
   {"Ứng dụng vẫn còn đăng ký cài đặt nên chỉ có thể xem. Hãy gỡ chính thức rồi quét lại để dọn.","The application is still registered as installed, so this list is view-only. Uninstall it officially, then scan again to clean."},{" Quét có thể chưa đầy đủ."," The scan may be incomplete."},
   {"Không hoàn tất quét.","Scan not completed."},{"Đã dừng quét — kết quả có thể chưa đầy đủ.","Scan stopped — results may be incomplete."},{"Hoàn tất quét.","Scan complete."},{"  Tìm thấy {0} mục.","  Found {0} items."},
